/**
 * Scenario: the iOS project is generated by Expo, so a StoreKit configuration
 * copied into it by hand, or by a script run after the build, is gone after the
 * next generation and the simulator's in-app purchases come back empty.
 *
 * Expected behaviour: generating the Dev identity copies the tracked StoreKit
 * configuration into the app directory and points the scheme's launch at it,
 * once however often generation runs. Production never carries it.
 */

import { mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

type ModRequest = { projectRoot: string; platformProjectRoot: string; projectName: string };
type Mod = { modRequest: ModRequest };
type Action = (mod: Mod) => Promise<Mod>;

let captured: { platform: string; action: Action } | null = null;

jest.mock('expo/config-plugins', () => ({
  ...jest.requireActual('expo/config-plugins'),
  withDangerousMod: (config: unknown, [platform, action]: [string, Action]) => {
    captured = { platform, action };
    return config;
  },
}));

const plugin = require('../../plugins/with-storekit-configuration');

const SCHEME = `<?xml version="1.0" encoding="UTF-8"?>
<Scheme>
   <LaunchAction
      buildConfiguration = "Debug"
      allowLocationSimulation = "YES">
      <BuildableProductRunnable
         runnableDebuggingMode = "0">
      </BuildableProductRunnable>
   </LaunchAction>
   <ProfileAction
      buildConfiguration = "Release">
   </ProfileAction>
</Scheme>
`;

const roots: string[] = [];

afterAll(() => {
  for (const root of roots) rmSync(root, { recursive: true, force: true });
});

function project(name: string): { root: string; scheme: string; request: ModRequest } {
  const root = mkdtempSync(join(tmpdir(), 'storekit-'));
  roots.push(root);
  mkdirSync(join(root, 'config'));
  writeFileSync(join(root, 'config/StoreKitConfiguration.storekit'), '{"products":["orchard"]}\n');
  const schemeDir = join(root, 'ios', `${name}.xcodeproj`, 'xcshareddata', 'xcschemes');
  mkdirSync(schemeDir, { recursive: true });
  mkdirSync(join(root, 'ios', name));
  const scheme = join(schemeDir, `${name}.xcscheme`);
  writeFileSync(scheme, SCHEME);
  return {
    root,
    scheme,
    request: { projectRoot: root, platformProjectRoot: join(root, 'ios'), projectName: name },
  };
}

function references(xml: string): number {
  return xml.split('<StoreKitConfigurationFileReference').length - 1;
}

describe('addStoreKitReference', () => {
  it('puts the reference inside the launch action and nowhere else', () => {
    const out = plugin.addStoreKitReference(SCHEME, '../Orchard/StoreKitConfiguration.storekit');

    const launch = out.slice(out.indexOf('<LaunchAction'), out.indexOf('</LaunchAction>'));
    expect(references(launch)).toBe(1);
    expect(references(out)).toBe(1);
    expect(launch).toContain('identifier = "../Orchard/StoreKitConfiguration.storekit"');
  });

  it('leaves a scheme that already has the reference unchanged', () => {
    const once = plugin.addStoreKitReference(SCHEME, '../Orchard/StoreKitConfiguration.storekit');
    expect(plugin.addStoreKitReference(once, '../Orchard/StoreKitConfiguration.storekit')).toBe(
      once
    );
  });

  it('refuses a scheme with no launch action rather than writing nothing', () => {
    expect(() =>
      plugin.addStoreKitReference('<Scheme></Scheme>', '../Orchard/StoreKitConfiguration.storekit')
    ).toThrow(/LaunchAction/);
  });
});

describe('with-storekit-configuration', () => {
  beforeEach(() => {
    captured = null;
  });

  it('copies the configuration into the app directory and patches the scheme', async () => {
    const { root, scheme, request } = project('Orchard');
    plugin({});
    expect(captured?.platform).toBe('ios');

    await captured!.action({ modRequest: request });

    expect(readFileSync(join(root, 'ios/Orchard/StoreKitConfiguration.storekit'), 'utf8')).toBe(
      '{"products":["orchard"]}\n'
    );
    const patched = readFileSync(scheme, 'utf8');
    expect(references(patched)).toBe(1);
    expect(patched).toContain('identifier = "../Orchard/StoreKitConfiguration.storekit"');
  });

  it('writes one reference when generation runs twice', async () => {
    const { scheme, request } = project('Orchard');
    plugin({});

    await captured!.action({ modRequest: request });
    await captured!.action({ modRequest: request });

    expect(references(readFileSync(scheme, 'utf8'))).toBe(1);
  });

  it('fails generation when the scheme is missing', async () => {
    const { scheme, request } = project('Orchard');
    rmSync(scheme);
    plugin({});

    await expect(captured!.action({ modRequest: request })).rejects.toThrow(/Orchard\.xcscheme/);
  });
});

describe('app.config.js', () => {
  const variant = process.env.APP_VARIANT;

  afterEach(() => {
    if (variant === undefined) delete process.env.APP_VARIANT;
    else process.env.APP_VARIANT = variant;
  });

  function plugins(appVariant: string | undefined): unknown[] {
    if (appVariant === undefined) delete process.env.APP_VARIANT;
    else process.env.APP_VARIANT = appVariant;
    let resolved: { plugins?: unknown[] } = {};
    jest.isolateModules(() => {
      const appConfig = require('../../../app.config.js');
      resolved = appConfig({
        config: {
          name: 'Veloq',
          plugins: ['expo-router'],
          android: { package: 'com.veloq.app' },
          ios: { bundleIdentifier: 'com.veloq.app' },
        },
      });
    });
    return resolved.plugins ?? [];
  }

  it('gives the Dev identity the StoreKit configuration', () => {
    expect(plugins(undefined)).toContain('./src/plugins/with-storekit-configuration');
  });

  it('keeps it out of production', () => {
    expect(plugins('production')).not.toContain('./src/plugins/with-storekit-configuration');
    expect(plugins('production')).toContain('expo-router');
  });
});
